package com.farika.soundflow;
import android.content.*;import android.content.res.AssetFileDescriptor;import android.database.*;import android.database.sqlite.*;import android.media.MediaMetadataRetriever;import android.net.Uri;import android.os.*;import android.os.storage.*;import android.provider.*;import java.io.*;import java.text.Collator;import java.util.*;
/** Device-local SAF references and per-file bookmarks. Never copies, uploads or caches audio bytes. */
public class LocalAudioStore {
 static final String EVENT="com.farika.soundflow.LOCAL_AUDIO_CHANGED";static final String PREFIX="local:";static final int READ=Intent.FLAG_GRANT_READ_URI_PERMISSION,WRITE=Intent.FLAG_GRANT_WRITE_URI_PERMISSION;
 public enum Sort { NEWEST,OLDEST,TITLE }
 public enum Access { AVAILABLE,MISSING,UNAVAILABLE,NO_PERMISSION }
 public static final class Metadata {final String title,artist;final long duration;Metadata(String title,String artist,long duration){this.title=title;this.artist=artist;this.duration=Math.max(0,duration);}}
 public static final class Entry {String id,document,title,artist;long duration,position,addedAt;String uri(){return PREFIX+id;}Library.Track track(){Library.Track t=new Library.Track(uri(),title,artist,duration,false);t.savedPosition=position;return t;}}
 public static final class Scan {final ArrayList<Entry> entries=new ArrayList<>();final ArrayList<String> removed=new ArrayList<>();int unavailable;}
 interface Check {void check()throws IOException;}
 private final Context context;
 private static final class Store extends SQLiteOpenHelper {Store(Context c){super(c,"local_audio.db",null,1);}public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE audio (id TEXT PRIMARY KEY,document TEXT NOT NULL UNIQUE,title TEXT NOT NULL,artist TEXT NOT NULL,duration INTEGER NOT NULL,position INTEGER NOT NULL,addedAt INTEGER NOT NULL)");}public void onUpgrade(SQLiteDatabase db,int old,int next){}}
 public LocalAudioStore(Context c){context=c.getApplicationContext();}
 public static boolean isLocal(String uri){return uri!=null&&uri.startsWith(PREFIX);}
 private static Entry entry(Cursor row){Entry e=new Entry();e.id=row.getString(row.getColumnIndexOrThrow("id"));e.document=row.getString(row.getColumnIndexOrThrow("document"));e.title=row.getString(row.getColumnIndexOrThrow("title"));e.artist=row.getString(row.getColumnIndexOrThrow("artist"));e.duration=row.getLong(row.getColumnIndexOrThrow("duration"));e.position=row.getLong(row.getColumnIndexOrThrow("position"));e.addedAt=row.getLong(row.getColumnIndexOrThrow("addedAt"));return e;}
 private Entry lookup(String column,String value){try(Store helper=new Store(context);Cursor rows=helper.getReadableDatabase().query("audio",null,column+"=?",new String[]{value},null,null,null)){return rows.moveToFirst()?entry(rows):null;}}
 public Entry get(String uri){return isLocal(uri)?lookup("id",uri.substring(PREFIX.length())):null;}
 public Library.Track find(String uri){Entry e=get(uri);return e==null?null:e.track();}
 public ArrayList<Entry> list(Sort sort){ArrayList<Entry> out=new ArrayList<>();try(Store helper=new Store(context);Cursor rows=helper.getReadableDatabase().query("audio",null,null,null,null,null,sort==Sort.OLDEST?"addedAt ASC,rowid ASC":"addedAt DESC,rowid DESC")){while(rows.moveToNext())out.add(entry(rows));}if(sort==Sort.TITLE){Collator collator=Collator.getInstance(new Locale("ru"));collator.setStrength(Collator.PRIMARY);out.sort((a,b)->{int cmp=collator.compare(a.title,b.title);return cmp==0?Long.compare(a.addedAt,b.addedAt):cmp;});}return out;}
 protected long now(){return System.currentTimeMillis();}
 protected boolean persistentRead(Uri uri){for(UriPermission p:context.getContentResolver().getPersistedUriPermissions())if(uri.equals(p.getUri())&&p.isReadPermission())return true;return false;}
 protected void take(Uri uri,int flags){context.getContentResolver().takePersistableUriPermission(uri,flags&(READ|WRITE));}
 protected void release(Uri uri){for(UriPermission p:context.getContentResolver().getPersistedUriPermissions())if(uri.equals(p.getUri()))try{context.getContentResolver().releasePersistableUriPermission(uri,(p.isReadPermission()?READ:0)|(p.isWritePermission()?WRITE:0));}catch(SecurityException ignored){}}
 protected Metadata metadata(Uri uri)throws Exception{ContentResolver resolver=context.getContentResolver();String name="Аудиофайл";try(Cursor rows=resolver.query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(rows!=null&&rows.moveToFirst()){String display=rows.getString(0);if(display!=null&&!display.trim().isEmpty())name=display;}}String type=resolver.getType(uri);if(type!=null&&!type.startsWith("audio/")&&!type.equals("application/ogg")&&!type.equals("application/octet-stream"))throw new IOException("Выбран не аудиофайл");try(AssetFileDescriptor fd=resolver.openAssetFileDescriptor(uri,"r")){if(fd==null)throw new IOException("Файл не удалось открыть");}String title=name,artist="Локальное аудио";long duration=0;MediaMetadataRetriever retriever=new MediaMetadataRetriever();try{retriever.setDataSource(context,uri);String t=retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_TITLE),a=retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_ARTIST),d=retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION);if(t!=null&&!t.trim().isEmpty())title=t;if(a!=null&&!a.trim().isEmpty())artist=a;if(d!=null)duration=Long.parseLong(d);}catch(RuntimeException ignored){/* A readable uncommon codec can still be offered to Media3. */}finally{retriever.release();}return new Metadata(title,artist,duration);}
 public Entry add(Uri uri,int flags)throws Exception{if(uri==null||!"content".equals(uri.getScheme()))throw new IOException("Выберите аудио через системный выбор файлов");boolean had=persistentRead(uri),committed=false;try{if((flags&READ)!=0)take(uri,flags);if(!persistentRead(uri))throw new IOException("Не удалось сохранить доступ к файлу. Выберите его через системный проводник.");Metadata m=metadata(uri);synchronized(LocalAudioStore.class){Entry old=lookup("document",uri.toString());String id=old==null?UUID.randomUUID().toString():old.id;ContentValues values=new ContentValues();values.put("document",uri.toString());values.put("title",m.title);values.put("artist",m.artist);values.put("duration",m.duration);values.put("position",old==null?0:clamp(old.position,m.duration));try(Store helper=new Store(context)){SQLiteDatabase db=helper.getWritableDatabase();if(old==null){values.put("id",id);values.put("addedAt",now());db.insertOrThrow("audio",null,values);}else db.update("audio",values,"id=?",new String[]{id});}committed=true;return get(PREFIX+id);}}finally{if(!committed&&!had)release(uri);}}
 private static long clamp(long p,long duration){return Math.max(0,duration>0?Math.min(p,duration):p);}
 public void position(String uri,long position,long duration){if(!isLocal(uri))return;synchronized(LocalAudioStore.class){ContentValues v=new ContentValues();v.put("position",clamp(position,duration));if(duration>0)v.put("duration",duration);try(Store helper=new Store(context)){helper.getWritableDatabase().update("audio",v,"id=?",new String[]{uri.substring(PREFIX.length())});}}}
 /** True only for mounted, local Android storage where FNF can be distinguished from unmount. */
 protected boolean localStorageReady(Uri uri){String authority=uri.getAuthority();if("com.android.externalstorage.documents".equals(authority)){try{String doc=DocumentsContract.getDocumentId(uri),volume=doc.substring(0,doc.indexOf(':'));StorageManager sm=context.getSystemService(StorageManager.class);if(sm==null)return false;for(StorageVolume v:sm.getStorageVolumes())if(volume.equalsIgnoreCase(v.getUuid())||volume.equals("primary")&&v.isPrimary())return Environment.MEDIA_MOUNTED.equals(v.getState())||Environment.MEDIA_MOUNTED_READ_ONLY.equals(v.getState());return false;}catch(Exception e){return false;}}return "com.android.providers.downloads.documents".equals(authority)||"com.android.providers.media.documents".equals(authority);}
 public Access probe(Entry e){Uri uri=Uri.parse(e.document);try{try(Cursor rows=context.getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(rows!=null){if(!rows.moveToFirst()){if("com.android.externalstorage.documents".equals(uri.getAuthority())&&!localStorageReady(uri))return Access.UNAVAILABLE;return Access.MISSING;}}}try(AssetFileDescriptor fd=context.getContentResolver().openAssetFileDescriptor(uri,"r")){return fd==null?Access.UNAVAILABLE:Access.AVAILABLE;}catch(FileNotFoundException missing){return localStorageReady(uri)?Access.MISSING:Access.UNAVAILABLE;}}catch(SecurityException denied){return Access.NO_PERMISSION;}catch(Exception unavailable){return Access.UNAVAILABLE;}}
 public Scan scan(Sort sort,Check check)throws IOException{Scan result=new Scan();for(Entry e:list(sort)){check.check();Access access=probe(e);check.check();if(access==Access.MISSING){remove(e.uri());result.removed.add(e.uri());}else{if(access!=Access.AVAILABLE)result.unavailable++;result.entries.add(e);}}return result;}
 /** Remove row and bookmark; never recreate from a late player checkpoint. */
 public void remove(String uri){Entry e; synchronized(LocalAudioStore.class){e=get(uri);if(e==null)return;try(Store helper=new Store(context)){helper.getWritableDatabase().delete("audio","id=?",new String[]{e.id});}PlaybackCheckpoint.forget(context,uri);}release(Uri.parse(e.document));context.sendBroadcast(new Intent(EVENT).setPackage(context.getPackageName()).putExtra("removed",uri));}
 protected boolean deleteDocument(Uri uri)throws Exception{return DocumentsContract.isDocumentUri(context,uri)?DocumentsContract.deleteDocument(context.getContentResolver(),uri):context.getContentResolver().delete(uri,null,null)>0;}
 public void deleteFile(String uri)throws Exception{Entry e=get(uri);if(e==null)return;Access access=probe(e);if(access==Access.MISSING){remove(uri);return;}boolean deleted=deleteDocument(Uri.parse(e.document));if(!deleted&&probe(e)!=Access.MISSING)throw new IOException("Проводник не разрешил удалить файл. Запись оставлена; можно удалить только из приложения.");remove(uri);}
}
